from functools import lru_cache


def path_stats(rows, cols):
    """Return (routes to (rows, cols), body executions).

    Each distinct (r, c) subproblem must execute at
    most once per query; the probe counts executions.
    """
    executions = 0

    @lru_cache(maxsize=None)
    def routes(r, c):
        nonlocal executions
        executions += 1  # the probe
        if r == 0 or c == 0:
            return 1
        return routes(r - 1, c) + routes(r, c - 1)

    return (routes(rows, cols), executions)
